<script lang="ts">
	import { goto, invalidateAll } from '$app/navigation';
	import { api, loadApi } from '$lib/api';
	import Modal from '$lib/components/Modal.svelte';
	let {data}=$props();
	let search=$state(''); let statusFilter=$state(''); let priorityFilter=$state('');
	let creating=$state(false); let selected=$state<any>(null); let history=$state<any[]>([]);
	let busy=$state(false); let error=$state(''); let notice=$state('');
	const coordinator=$derived(data.user?.role==='PERAWAT'&&data.user?.coordinator);
	const visible=$derived(data.tasks);
	async function filterTasks(nextPage=0){const q=new URLSearchParams({page:String(nextPage)});if(search.trim())q.set('search',search.trim());if(statusFilter)q.set('status',statusFilter);if(priorityFilter)q.set('priority',priorityFilter);await goto(`/tasks?${q}`,{keepFocus:true,noScroll:true});}
	const statuses=[['todo','Belum Dikerjakan'],['in_progress','Sedang Dikerjakan'],['done','Selesai'],['cancelled','Dibatalkan']];
	const placements=$derived(data.reference.placements.filter((p:any)=>p.status==='active'));
	async function reloadHistory(id:string){try{const result=await loadApi<{items:any[]}>(fetch,`/tasks/${id}/history`);history=result.items;}catch{history=[];}}
	async function open(task:any){const id=typeof task==='string'?task:task.id;error='';try{selected=await api<any>(`/tasks/${id}`);await reloadHistory(id);}catch(failure){error=(failure as Error).message;selected=null;}}
	async function submit(path:string,method:string,payload:object){busy=true;error='';notice='';const selectedId=selected?.id;try{const result=await api<any>(path,{method,body:JSON.stringify(payload)});await invalidateAll();if(result?.id&&result.id===selectedId)selected=result;notice='Perubahan berhasil disimpan.';return true;}catch(e){error=e instanceof Error?e.message:'Perubahan gagal disimpan.';return false;}finally{busy=false;}}
	async function createTask(event:SubmitEvent){event.preventDefault();const f=new FormData(event.currentTarget as HTMLFormElement);const placement=placements.find((p:any)=>p.id===f.get('placementId'));if(!placement){error='Pilih penempatan pasien yang masih aktif.';return;}const toIso=(s:string)=>new Date(s).toISOString();const ok=await submit('/tasks','POST',{patientId:placement.patientId,placementId:placement.id,picId:f.get('picId'),title:f.get('title'),description:f.get('description'),notes:f.get('notes'),priority:f.get('priority'),startsAt:toIso(String(f.get('startsAt'))),endsAt:toIso(String(f.get('endsAt')))});if(ok)creating=false;}
	async function changeStatus(task:any,status:string){const reason=status==='cancelled'?window.prompt('Alasan pembatalan tugas:')?.trim():undefined;if(status==='cancelled'&&!reason)return;if(await submit(`/tasks/${task.id}`,'PATCH',{expectedVersion:task.version,status,reason}))await open(task.id);}
	async function addNote(event:SubmitEvent){event.preventDefault();const f=new FormData(event.currentTarget as HTMLFormElement);if(await submit(`/tasks/${selected.id}`,'PATCH',{expectedVersion:selected.version,notes:f.get('notes')}))await open(selected.id);}
	async function reassign(event:SubmitEvent){event.preventDefault();const f=new FormData(event.currentTarget as HTMLFormElement);if(await submit(`/tasks/${selected.id}/reassign`,'POST',{expectedVersion:selected.version,picId:f.get('picId'),reason:f.get('reason')}))await open(selected.id);}
	async function removeTask(){if(!selected)return;const reason=prompt('Alasan penghapusan logis:');if(!reason?.trim())return;if(await submit(`/tasks/${selected.id}`,'DELETE',{expectedVersion:selected.version,reason}))selected=null;}
	function local(value:string){return new Date(value).toLocaleString('id-ID',{dateStyle:'medium',timeStyle:'short'});}
</script>

<svelte:head><title>Tugas Perawatan | InpaCare</title></svelte:head>
<section class="page-heading"><div><h1 class="page-title">Tugas Perawatan</h1><p class="page-subtitle">Tugas pasien dengan PIC, rentang waktu, prioritas, dan riwayat perubahan.</p></div>{#if coordinator}<button class="button primary" onclick={()=>{creating=!creating;error='';}}>＋ Buat tugas</button>{/if}</section>
{#if error}<p class="error" role="alert">{error}</p>{/if}{#if notice}<p class="success" role="status">{notice}</p>{/if}
<section class="stats" aria-label="Ringkasan tugas">{#each statuses as [key,label]}<div class="stat"><strong>{data.counts[key]??0}</strong><span>{label}</span></div>{/each}</section>
{#if creating&&coordinator}<section class="panel form-panel"><h2>Buat tugas perawatan</h2><form class="form-grid" onsubmit={createTask}>
	<label class="field">Penempatan pasien<select name="placementId" required><option value="">Pilih pasien / ruangan</option>{#each placements as p}<option value={p.id}>{p.patientName} · {p.roomName} ({p.startsOn}–{p.endsOn})</option>{/each}</select></label>
	<label class="field">Perawat PIC<select name="picId" required><option value="">Pilih PIC aktif</option>{#each data.reference.staff.filter((u:any)=>u.role==='PERAWAT'&&u.active) as nurse}<option value={nurse.id}>{nurse.name}</option>{/each}</select></label>
	<label class="field">Judul<input name="title" required maxlength="150" /></label><label class="field">Prioritas<select name="priority"><option value="normal">Normal</option><option value="high">Tinggi</option><option value="low">Rendah</option></select></label>
	<label class="field">Waktu mulai<input name="startsAt" type="datetime-local" required /></label><label class="field">Waktu selesai<input name="endsAt" type="datetime-local" required /></label>
	<label class="field">Deskripsi<textarea name="description" rows="2"></textarea></label><label class="field">Catatan awal<textarea name="notes" rows="2"></textarea></label>
	<div class="form-actions"><button class="button primary" disabled={busy}>Simpan tugas</button><button class="button secondary" type="button" onclick={()=>creating=false}>Batal</button></div>
</form></section>{/if}
<section class="panel"><form class="filters" onsubmit={(event)=>{event.preventDefault();void filterTasks();}}><label class="field search-field">Cari tugas atau pasien<input bind:value={search} placeholder="Nama pasien, nomor RM, judul tugas" /></label><label class="field">Status<select bind:value={statusFilter}><option value="">Semua status</option>{#each statuses as [key,label]}<option value={key}>{label}</option>{/each}</select></label><label class="field">Prioritas<select bind:value={priorityFilter}><option value="">Semua prioritas</option><option value="high">Tinggi</option><option value="normal">Normal</option><option value="low">Rendah</option></select></label><button class="button primary" type="submit">Terapkan filter</button><span class="muted">{data.total} tugas dalam cakupan Anda</span></form></section>
<div class="panel-header"><span class="muted">Menampilkan {data.total?data.page*50+1:0}–{Math.min(data.page*50+50,data.total)} dari {data.total} tugas</span><div class="card-actions"><button class="button small" disabled={data.page===0} onclick={()=>filterTasks(data.page-1)}>Sebelumnya</button><button class="button small" disabled={(data.page+1)*50>=data.total} onclick={()=>filterTasks(data.page+1)}>Berikutnya</button></div></div><div class="task-board">{#each statuses as [key,label]}<section class="task-column" aria-label={label}><div class="column-heading"><strong>{label}</strong><span>{visible.filter((t:any)=>t.status===key).length}</span></div>{#each visible.filter((t:any)=>t.status===key) as task (task.id)}<article class="task-card"><div class="task-card-top"><span class="badge {task.priority==='high'?'warning':''}">Prioritas {task.priority==='high'?'Tinggi':task.priority==='low'?'Rendah':'Normal'}</span><button class="text-link" onclick={()=>open(task)}>Detail →</button></div><h3>{task.title}</h3><p><strong>{task.patientName}</strong> · {task.roomName}</p><p class="muted">{local(task.startsAt)} – {local(task.endsAt)}</p><p class="muted">PIC: {task.picName}</p><div class="card-actions"><button class="button secondary small" onclick={()=>open(task)}>Riwayat / catatan</button>{#if task.status==='todo'&&task.picId===data.user.id}<button class="button primary small" disabled={busy} onclick={()=>changeStatus(task,'in_progress')}>Mulai</button>{:else if task.status==='in_progress'&&task.picId===data.user.id}<button class="button primary small" disabled={busy} onclick={()=>changeStatus(task,'done')}>Selesaikan</button>{/if}</div></article>{:else}<p class="empty">Tidak ada tugas.</p>{/each}</section>{/each}</div>
{#if selected}<Modal title={selected.title} onclose={()=>selected=null}><div class="panel-header"><div><h2 id="task-dialog-title">{selected.title}</h2><p class="muted">{selected.patientName} · {selected.roomName} · {selected.picName}</p></div><button class="button secondary small" onclick={()=>selected=null} aria-label="Tutup detail">Tutup</button></div>{#if error}<p class="error" role="alert">{error}</p>{/if}<p>{selected.description||'Tidak ada deskripsi.'}</p><p><strong>Catatan:</strong> {selected.notes||'Belum ada catatan.'}</p><p class="muted">{local(selected.startsAt)} – {local(selected.endsAt)} · versi {selected.version}</p>
	{#if data.user.id===selected.picId||coordinator}<form class="inline-edit" onsubmit={addNote}><label class="field">Catatan tindakan<textarea name="notes" rows="2" maxlength="3000" required>{selected.notes}</textarea></label><button class="button secondary small" disabled={busy}>Simpan catatan</button></form>{/if}
	{#if coordinator&&selected.status!=='done'&&selected.status!=='cancelled'}<form class="inline-edit" onsubmit={reassign}><label class="field">Alihkan ke perawat<select name="picId" required>{#each data.reference.staff.filter((u:any)=>u.role==='PERAWAT'&&u.active&&u.id!==selected.picId) as nurse}<option value={nurse.id}>{nurse.name}</option>{/each}</select></label><label class="field">Alasan pengalihan<input name="reason" required maxlength="500" /></label><button class="button secondary small" disabled={busy}>Alihkan PIC</button></form><div class="card-actions"><button class="button danger small" disabled={busy||selected.status==='cancelled'} onclick={()=>changeStatus(selected,'cancelled')}>Batalkan dengan alasan</button><button class="button danger small" disabled={busy} onclick={removeTask}>Hapus logis dengan alasan</button></div>{/if}
	<h3>Riwayat tugas</h3><ol class="history-list">{#each history as item}<li><strong>{item.action}</strong> · {item.actorName} <time>{local(item.createdAt)}</time>{#if item.reason}<p>{item.reason}</p>{/if}</li>{:else}<li class="muted">Belum ada riwayat.</li>{/each}</ol></Modal>{/if}

<style>
.task-board{display:grid;grid-template-columns:repeat(4,minmax(210px,1fr));gap:12px;align-items:start;margin-top:16px}.task-column{min-height:170px;border-radius:10px;padding:10px;background:#f3f4f6}.column-heading{display:flex;justify-content:space-between;padding:3px 2px 10px;color:#40465a;font-size:12px}.task-card{background:#fff;border:1px solid #e5e7eb;border-radius:9px;padding:12px;margin-bottom:9px;box-shadow:0 1px 2px #1319270a}.task-card h3{font-size:14px;margin:9px 0 6px;color:#131927}.task-card p{font-size:12px;margin:5px 0}.task-card-top,.card-actions{display:flex;align-items:center;justify-content:space-between;gap:8px}.card-actions{justify-content:flex-start;margin-top:10px;flex-wrap:wrap}.inline-edit{display:flex;align-items:end;gap:10px;flex-wrap:wrap;margin:12px 0}.history-list{padding-left:20px}.history-list li{padding:6px 0}.history-list time{display:block;color:#747b8c;font-size:12px}.history-list p{margin:3px 0}@media(max-width:1050px){.task-board{grid-template-columns:repeat(2,minmax(200px,1fr))}}@media(max-width:620px){.task-board{grid-template-columns:1fr}}
</style>
